from jsonb_to_recordset($json$[{"id":"che-so-126","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Molarity of a sealed bottle of solution falls slightly on heating because","options":["moles of solute decrease","the solution volume expands","the solvent mass vanishes","mole fraction becomes undefined"],"answer_index":1,"explanation":"Thermal expansion increases V while n stays fixed, so M = n/V drops.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-127","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Normality of a solution is the number of","options":["gram equivalents of solute in one litre of solution","moles of solute in one kilogram of solvent","mole fraction units per litre","ppm units per kilogram"],"answer_index":0,"explanation":"N = gram equivalents of solute / litres of solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-128","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mole fraction is a concentration that is","options":["measured in mol L⁻¹","dimensionless","reported in kg mol⁻¹","identical to ppm"],"answer_index":1,"explanation":"It is a pure number — a ratio of moles to moles.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-129","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A student dissolves 10 g of NaOH in 90 g of water. The mass percent of NaOH is","options":["10%","11.1%","9.0%","90%"],"answer_index":0,"explanation":"Mass of solution = 100 g, so w/w % = 10/100 × 100 = 10%.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-130","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two moles of ethanol are mixed with three moles of water. Mole fraction of ethanol is","options":["0.40","0.60","0.50","0.67"],"answer_index":0,"explanation":"$x_{\\mathrm{EtOH}} = 2 / (2 + 3) = 0.40$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-131","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"4.9 g of H2SO4 (98 g mol⁻¹) made up to 500 mL of solution has molarity","options":["0.10 M","0.20 M","0.05 M","1.0 M"],"answer_index":0,"explanation":"Moles = 4.9/98 = 0.050; volume = 0.50 L, so M = 0.10 mol L⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-132","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dissolving 6.0 g of urea (60 g mol⁻¹) in 250 g of water produces molality","options":["0.40 m","0.25 m","0.10 m","1.0 m"],"answer_index":0,"explanation":"Moles of urea = 0.10; kilograms of water = 0.250, so m = 0.40 mol kg⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-133","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 100 ppm aqueous impurity corresponds, in 1.0 kg of solution, to a solute mass of","options":["100 mg","100 g","1.0 g","10 mg"],"answer_index":0,"explanation":"100 × 10⁻⁶ × 1000 g = 0.100 g = 100 mg.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-134","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Glucose (180 g mol⁻¹), 9.0 g, sits together with 81 g of water. Mole fraction of glucose is nearest","options":["0.011","0.10","0.050","0.90"],"answer_index":0,"explanation":"n(glucose) = 0.050, n(water) = 4.50, so x = 0.050/4.55 ≈ 0.011.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-135","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An aqueous bottle labelled 2.0 M NaCl occupies 250 mL. Moles of NaCl inside are","options":["0.50","2.0","0.25","8.0"],"answer_index":0,"explanation":"n = M V = 2.0 mol L⁻¹ × 0.250 L = 0.50 mol.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-136","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Aqueous HCl is 36.5% (w/w) with density 1.18 g mL⁻¹. Using molar mass 36.5 g mol⁻¹, the molarity is nearest","options":["11.8 M","10.0 M","1.18 M","36.5 M"],"answer_index":0,"explanation":"One litre has mass 1180 g and contains 0.365 × 1180 = 431 g HCl, i.e. 11.8 mol, so M ≈ 11.8.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-137","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A flask holds 8.0 g of CH3OH (32 g mol⁻¹) plus 36 g of water. Molality of methanol is nearest","options":["6.9 m","0.25 m","4.0 m","2.2 m"],"answer_index":0,"explanation":"n(CH3OH) = 0.25 mol in 0.036 kg of water, so m = 0.25/0.036 ≈ 6.9 mol kg⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-138","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mixing 200 mL of 0.60 M H2SO4 with 300 mL of 0.20 M H2SO4, taking volumes as additive, gives a blend of","options":["0.36 M","0.40 M","0.80 M","0.24 M"],"answer_index":0,"explanation":"Moles = 0.12 + 0.06 = 0.18 in 0.50 L, so M = 0.36 mol L⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-139","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Henry linked the partial pressure of a dissolved gas to its","options":["mole fraction in the liquid","mass percent alone","molality squared","normal boiling point"],"answer_index":0,"explanation":"One form is $p = K_H x$, with x the mole fraction of the dissolved gas.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-140","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The Henry-law constant $K_H$ is dimensionally a","options":["pressure","volume","molality","entropy"],"answer_index":0,"explanation":"Because $p = K_H x$ and x is dimensionless, $K_H$ has the unit of pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-141","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At a fixed temperature, a larger $K_H$ for a gas means that gas is","options":["more soluble","less soluble","exactly as soluble as every other gas","always immiscible"],"answer_index":1,"explanation":"x = p / $K_H$, so a large constant implies a small dissolved mole fraction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-142","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Soft-drink bottles are packed under extra carbon-dioxide pressure so that","options":["more CO2 remains dissolved until the cap is opened","$K_H$ becomes zero","the drink freezes in the bottle","oxygen is chemically removed"],"answer_index":0,"explanation":"Higher p(CO2) forces a larger x(CO2) in the liquid (Henry’s law).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-143","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Deep-sea divers risk decompression sickness because nitrogen","options":["dissolves more at high pressure and bubbles out on a rapid ascent","is insoluble at depth","binds irreversibly to haemoglobin only","forms an azeotrope with blood plasma"],"answer_index":0,"explanation":"High p(N2) loads the blood; a sudden drop in pressure releases bubbles in the tissues.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-144","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Warming a solvent generally","options":["raises $K_H$ and lowers gas solubility","lowers $K_H$ and raises gas solubility","leaves gas solubility untouched","ionises the dissolved gas"],"answer_index":0,"explanation":"Gas dissolution is exothermic, so $K_H$ increases and x falls as T rises.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-145","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A compact statement of Henry’s law for a sparingly soluble gas is","options":["$p = K_H x$","$p = K_H / x$","$p = x / K_H^2$","$\\pi = CRT$"],"answer_index":0,"explanation":"Partial pressure of the gas is proportional to its mole fraction in the solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-146","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At 298 K, $K_H$ for N2 in water is 8.0 × 10⁴ atm. Under 0.80 atm of nitrogen the dissolved mole fraction is","options":["1.0 × 10⁻⁵","8.0 × 10⁻⁴","0.80","1.0 × 10⁻³"],"answer_index":0,"explanation":"x = p / $K_H$ = 0.80 / 8.0 × 10⁴ = 1.0 × 10⁻⁵.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-147","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two gases have $K_H$ values 2 × 10³ atm and 5 × 10⁴ atm. At the same partial pressure the more soluble gas is the one with","options":["$K_H$ = 2 × 10³ atm","$K_H$ = 5 × 10⁴ atm","equal solubility in both cases","neither gas dissolving"],"answer_index":0,"explanation":"Solubility falls as $K_H$ rises, so the smaller constant marks the more soluble gas.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-148","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A mountaineer takes up less oxygen at high altitude mainly because","options":["the partial pressure of O2 in the air is lower","$K_H$ of oxygen becomes zero","blood volume instantly doubles","nitrogen is absent from the atmosphere"],"answer_index":0,"explanation":"Henry’s law: dissolved x(O2) tracks p(O2), which falls as total air pressure falls.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-149","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"If the partial pressure of CO2 above a drink is doubled at constant temperature, the dissolved mole fraction of CO2","options":["doubles","halves","becomes four times","stays exactly the same"],"answer_index":0,"explanation":"x ∝ p at fixed T, so doubling p doubles the dissolved mole fraction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-150","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dry air is 0.21 mole fraction oxygen. With $K_H$(O2) = 3.3 × 10⁷ torr and a total air pressure of 760 torr, dissolved x(O2) is nearest","options":["4.8 × 10⁻⁶","2.1 × 10⁻¹","3.3 × 10⁻⁷","1.6 × 10⁻⁴"],"answer_index":0,"explanation":"p(O2) = 0.21 × 760 = 160 torr; x = 160 / 3.3 × 10⁷ ≈ 4.8 × 10⁻⁶.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
